function hero(sur,ownRate){let income=n(S.profile.salary)+n(S.profile.otherIncome),pct=Math.min(100,Math.max(0,ownRate/Math.max(1,income)*100)),c=2*Math.PI*74;return `<section class="card hero"><div><span class="pill">● MODEL FINANCIAR PERSONAL</span><div class="kicker" style="margin-top:20px">Marjă lunară înainte de ING</div><div class="big ${sur>=0?'good':'bad'}">${money(sur)}</div><div class="hero-sub">${known(S.profile.extraLiving)?'Buget de trai introdus.':'Cheltuielile de trai suplimentare nu sunt încă introduse.'} Ratele părinților rămân separate până la preluare.</div><div class="actions"><button class="primary" data-av-click="go('debts')">Completează creditele</button><button data-av-click="go('decision')">Test de achiziție →</button></div></div><svg class="orbit" viewBox="0 0 200 200" role="img" aria-label="Pondere rate proprii în venit"><circle cx="100" cy="100" r="74" fill="none" stroke="#a4c8b4" stroke-opacity=".2" stroke-width="12"/><circle cx="100" cy="100" r="74" fill="none" stroke="#86a8ff" stroke-width="12" stroke-linecap="round" stroke-dasharray="${c*pct/100} ${c}" transform="rotate(-90 100 100)"/><circle cx="100" cy="100" r="59" fill="none" stroke="#9fd2c4" stroke-opacity=".16" stroke-dasharray="2 5"/><text x="100" y="99" text-anchor="middle" font-size="33" font-weight="650">${pct.toFixed(1)}%</text><text x="100" y="121" text-anchor="middle" font-size="11">rate / venit</text></svg></section>`}
let decisionState={amount:0,date:iso(add(date(S.profile.asof),14)),months:6};function decision(){let d=decisionState,b=schedule(d.months),applied=b.daily.some(x=>x.ds===d.date),cost=n(d.amount),after=b.daily.map(x=>({...x,bal:x.bal-(applied&&x.ds>=d.date?cost:0)})),min=Math.min(cash(),...after.map(x=>x.bal)),first=after.find(x=>x.bal<0),complete=isReady();let label=!applied?'Data în afara prognozei':!complete?'Date incomplete — decizie neconfirmată':min<0?'Risc de deficit':min<n(S.profile.buffer)?'Rezerva scade sub obiectiv':'Încape în model';let months=b.monthly.map(m=>({key:m.key,bal:after.filter(x=>x.ds.startsWith(m.key)).at(-1)?.bal??m.bal}));return `<div class="card"><div class="kicker">Decision lab</div><h2>Îmi permit această achiziție?</h2><div class="fields"><label>Cost (lei)<input type="number" min="0" step="any" value="${esc(d.amount)}" data-av-change="setDecision('amount',this.value)"></label><label>Data achiziției<input type="date" value="${esc(d.date)}" data-av-change="setDecision('date',this.value)"></label><label>Orizont (luni)<input type="number" min="1" max="60" value="${d.months}" data-av-change="setDecision('months',this.value)"></label></div><p class="notice">${label}. Nu este recomandare de cumpărare; modelul include doar obligațiile și cheltuielile introduse.</p><div class="grid">${metric('Minim fără achiziție',money(b.low))}${metric('Minim după achiziție',money(min),'Sold la final de zi',min<0?'bad':'good')}${metric('Primul deficit',first?.ds||'Niciunul în model')}${metric('Diferență la final',money(applied?-cost:0))}</div>${graph([{vals:[cash(),...b.monthly.map(x=>x.bal)],color:'#c2a9fa',label:'Fără achiziție'},{vals:[cash(),...months.map(x=>x.bal)],color:'#86a8ff',label:'Cu achiziție'}])}</div>${notice()}`};function setDecision(k,v){decisionState[k]=k==='date'?v:k==='months'?Math.max(1,Math.min(60,Math.floor(n(v)))):Math.max(0,n(v));render(true)}
function overview(){let base=schedule(12),all=rates(true),ownRate=rates(),sur=net();return `${hero(sur,ownRate)}<div class="grid">${metric('Salariu net / lună',money(S.profile.salary),'Tichete separat: '+money(S.profile.tickets))}${metric('Rate plătite de tine',money(ownRate),(ownRate/n(S.profile.salary)*100||0).toFixed(1)+'% din salariu','warn')}${metric('Rate suportate de părinți',money(all-ownRate),'Obligații economice asumate')}${metric('Surplus lunar provizoriu',money(sur),'Înainte de ING net și împrumuturi personale',sur>=0?'good':'bad')}</div><div class="grid two"><div class="card"><h2>Distribuția lunară</h2><div class="bar">${[[ownRate,'#ff9aab'],[recur(),'#87b9ff'],[n(S.profile.extraLiving),'#ffd191'],[Math.max(0,sur),'#6ee7bd']].map(([v,c])=>`<span style="width:${v/Math.max(1,n(S.profile.salary)+n(S.profile.otherIncome),ownRate+recur()+n(S.profile.extraLiving))*100}%;background:${c}"></span>`).join('')}</div>${[['Rate proprii',ownRate],['Cheltuieli recurente',recur()],['Alte cheltuieli',n(S.profile.extraLiving)],['Surplus înainte de ING',sur],['Surplus dacă preiei toate ratele',sur-(all-ownRate)]].map(([l,v])=>`<div class="row"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}<div class="line"></div><div class="tiny muted">Transferurile între conturile proprii nu reprezintă cheltuieli. Ratele sunt contabilizate o singură dată, în funcție de plătitor.</div></div><div class="card"><h2>Obligații pe termen scurt</h2>${[['ING – sold utilizat',S.card.balance],...S.personal.map(p=>[p.name,p.balance])].map(([l,v])=>`<div class="row"><span>${esc(l)}</span><strong>${money(v)}</strong></div>`).join('')}<div class="line"></div><div class="row"><span>Plăți nete ING estimate</span><strong>${known(S.card.due)&&known(S.card.reuse)?money(dueCard()):'Necunoscut'}</strong></div><p class="tiny muted">Rambursarea urmată de reutilizare nu stinge automat datoria. Nu tratăm creditul reutilizat ca venit.</p><button data-av-click="go('debts')">Completează datoriile</button></div></div><div class="card"><div class="row"><h2>Prognoza soldului · 12 luni</h2><span class="pill">Provizorie</span></div>${graph([{vals:[cash(),...base.monthly.map(x=>x.bal)],color:'#6ee7bd'}])}<div class="grid">${metric('Sold inițial introdus',money(cash()),knownCash()?'Complet':'Incomplet')}${metric('Minim proiectat',money(base.low),'Sold la final de zi',base.low<0?'bad':'good')}${metric('Primul deficit',base.first?base.first.ds:'Niciunul în model','Nu include sumele necunoscute')}${metric('Minim în cursul zilei',money(base.intradayLow),'În ordinea simulată a plăților',base.intradayLow<0?'bad':'good')}</div><p class="tiny muted">Țintă rezervă: ${money(S.profile.buffer)}. Diferență față de soldul introdus: ${money(Math.max(0,n(S.profile.buffer)-cash()))}. Ordinea intrazilnică presupune încasarea salariului înaintea plăților din aceeași zi.</p></div>${notice()}`}
function debts(){return `<div class="grid">${metric('Rate proprii',money(rates()))}${metric('Toate ratele economice',money(rates(true)))}${metric('Solduri cunoscute',money(S.debts.reduce((s,d)=>s+n(d.balance),0)+n(S.card.balance)+S.personal.reduce((s,p)=>s+n(p.balance),0)),'Total incomplet dacă există solduri necompletate')}</div><div class="card"><h2>Credite bancare</h2><p class="muted tiny">Titularul legal și persoana care plătește în prezent sunt câmpuri distincte. Data preluării plății este opțională.</p>${S.debts.map((d,i)=>`<details class="debt"><summary><div><strong>${esc(d.name)}</strong><div class="tiny muted">${esc(d.owner)} · plătește ${esc(d.payer)} · ziua ${esc(d.day)}</div></div><strong>${money(d.rate)}</strong></summary><div class="fields">${fld('Denumire',`debts.${i}.name`,d.name,'text')}${sel('Titular legal',`debts.${i}.owner`,d.owner,[['Eu','Eu'],['Tată','Tată'],['Mamă','Mamă'],['Altul','Altul']])}${sel('Plătește acum',`debts.${i}.payer`,d.payer,[['Eu','Eu'],['Tată','Tată'],['Mamă','Mamă'],['Altul','Altul']])}${fld('Sold rămas (lei)',`debts.${i}.balance`,d.balance)}${fld('Rată (lei)',`debts.${i}.rate`,d.rate)}${fld('Zi scadentă',`debts.${i}.day`,d.day,'number','max="31"')}${fld('Dobândă anuală %',`debts.${i}.interest`,d.interest)}${fld('Ultima rată',`debts.${i}.end`,d.end,'date')}${fld('Preiau plata din',`debts.${i}.takeover`,d.takeover,'date')}${fld('Comision închidere (lei)',`debts.${i}.fees`,d.fees)}${fld('Observații',`debts.${i}.note`,d.note,'text')}</div><button class="danger" data-av-click="removeItem('debts',${i})">Elimină creditul</button></details>`).join('')}<button data-av-click="addDebt()">+ Credit</button></div><div class="card"><h2>Card ING · credit revolving</h2><div class="row"><strong>${money(S.card.balance)} utilizat din ${money(S.card.limit)}</strong><span class="pill">${S.card.limit?(S.card.balance/S.card.limit*100).toFixed(0):0}% utilizat</span></div><div class="bar"><span style="width:${Math.min(100,n(S.card.balance)/Math.max(1,n(S.card.limit))*100)}%;background:#ff9aab"></span></div><div class="fields">${fld('Limită','card.limit',S.card.limit)}${fld('Sold utilizat','card.balance',S.card.balance)}${fld('Sumă de plată pe extras','card.due',S.card.due)}${fld('Zi scadentă','card.day',S.card.day,'number','max="31"')}${fld('Sumă reutilizată după plată','card.reuse',S.card.reuse)}${fld('Costuri lunare estimate','card.fees',S.card.fees)}${fld('Dobândă anuală % (informativ)','card.interest',S.card.interest)}${fld('Observații','card.note',S.card.note,'text')}</div><div class="notice">Modelul folosește o plată și o reutilizare lunară constante, doar pentru simulare. Nu presupune că top-up-ul va rămâne eligibil pentru rate sau că este gratuit. Introdu sumele reale din extras. Plata brută trebuie să fie disponibilă înaintea reutilizării.</div><div class="row"><span>Reducerea lunară estimată a principalului, înainte de alte costuri</span><strong>${known(S.card.due)&&known(S.card.reuse)?money(n(S.card.due)-n(S.card.reuse)-n(S.card.fees)):'Necunoscută'}</strong></div></div><div class="card"><h2>Împrumuturi personale</h2>${S.personal.map((p,i)=>`<details class="debt" open><summary><strong>${esc(p.name)}</strong><strong>${money(p.balance)}</strong></summary><div class="fields">${fld('Persoană',`personal.${i}.name`,p.name,'text')}${fld('Sold rămas',`personal.${i}.balance`,p.balance)}</div>${p.plan.map((e,j)=>`<div class="fields">${fld('Data plății',`personal.${i}.plan.${j}.date`,e.date,'date')}${fld('Sumă',`personal.${i}.plan.${j}.amount`,e.amount)}<button data-av-click="delPlan(${i},${j})">Elimină</button></div>`).join('')}<p class="tiny muted">Neprogramat: ${money(Math.max(0,n(p.balance)-p.plan.reduce((s,e)=>s+n(e.amount),0)))}</p>${p.plan.reduce((s,e)=>s+n(e.amount),0)>n(p.balance)?'<p class="bad">Plățile programate depășesc soldul.</p>':''}<button data-av-click="addPlan(${i})">+ Tranșă</button> <button class="danger" data-av-click="removeItem('personal',${i})">Elimină împrumutul</button></details>`).join('')}<button data-av-click="addPersonal()">+ Împrumut</button></div>`}
function budget(){let p=S.profile;return `${known(p.cashTotal)?'<div class="notice">Proiecția folosește soldul consolidat. <button data-av-click="clearTotal()">Folosește soldurile individuale</button></div>':''}<div class="card"><h2>Venituri și dată de referință</h2><div class="fields">${fld('Data situației (solduri la finalul zilei)','profile.asof',p.asof,'date')}${fld('Salariu net','profile.salary',p.salary)}${metric('Următorul salariu',iso(nextSalary()),'A patra zi lucrătoare')}${fld('Tichete de masă (separat)','profile.tickets',p.tickets)}${fld('Alte venituri lunare','profile.otherIncome',p.otherIncome)}${fld('Ziua altor venituri','profile.otherDay',p.otherDay,'number','max="31"')}${fld('Alte cheltuieli lunare, peste tichete','profile.extraLiving',p.extraLiving)}${fld('Rezervă minimă dorită','profile.buffer',p.buffer)}</div><div class="fields">${fld('Excepții salariale (date YYYY-MM-DD, separate prin spațiu)','profile.salaryOverrides',p.salaryOverrides||'','text')}${fld('Zile libere suplimentare (YYYY-MM-DD)','profile.extraHolidays',p.extraHolidays||'','text')}</div><p class="tiny muted">Salariul de lucru poate fi ales din istoricul importat. Tichetele intră pe 10 sau în ultima zi lucrătoare anterioară; nu intră în soldul bancar. Calendarul folosește sărbătorile legale românești și Paștele ortodox, fără punți neconfirmate. Alte cheltuieli se distribuie zilnic în simulare.</p></div><div class="card"><h2>Solduri și conturi</h2>${S.accounts.map((a,i)=>`<details class="debt" open><summary><strong>${esc(a.name)}</strong><span>${known(a.balance)?money(a.balance):'Necompletat'}</span></summary><div class="fields">${fld('Cont',`accounts.${i}.name`,a.name,'text')}${fld('Sold disponibil, fără limita de credit',`accounts.${i}.balance`,a.balance)}${fld('Rulaj lunar necesar',`accounts.${i}.minTurnover`,a.minTurnover)}${fld('Comision dacă nu îndeplinesc condiția',`accounts.${i}.fee`,a.fee)}</div><button class="danger" data-av-click="removeItem('accounts',${i})">Elimină</button></details>`).join('')}<button data-av-click="addAccount()">+ Cont</button><p class="tiny muted">Soldurile sunt consolidate. Nu simulăm distribuția pe fiecare cont sau îndeplinirea efectivă a condițiilor bancare. Rulajul între conturile proprii este informativ, nu cost.</p></div><div class="card"><h2>Cheltuieli recurente · ${money(recur())}/lună</h2>${S.recurring.map((c,i)=>`<details class="debt" open><summary><strong>${esc(c.name)}</strong><span>${money(c.amount)} / ${({weekly:'săpt.',biweekly:'2 săpt.',monthly:'lună',yearly:'an'})[c.frequency]}</span></summary><div class="fields">${fld('Denumire',`recurring.${i}.name`,c.name,'text')}${fld('Sumă',`recurring.${i}.amount`,c.amount)}${sel('Frecvență',`recurring.${i}.frequency`,c.frequency,[['weekly','Săptămânal'],['biweekly','La două săptămâni'],['monthly','Lunar'],['yearly','Anual']])}${c.frequency==='monthly'?fld('Ziua lunii',`recurring.${i}.day`,c.day,'number','max="31"'):fld('Data unei plăți viitoare de referință',`recurring.${i}.anchor`,c.anchor,'date')}</div><button class="danger" data-av-click="removeItem('recurring',${i})">Elimină</button></details>`).join('')}<button data-av-click="addRecurring()">+ Cheltuială recurentă</button></div><div class="card"><h2>Evenimente și plăți unice</h2>${S.events.map((e,i)=>`<div class="debt"><div class="fields">${fld('Denumire',`events.${i}.name`,e.name,'text')}${fld('Data',`events.${i}.date`,e.date,'date')}${fld('Sumă',`events.${i}.amount`,e.amount)}${sel('Tip',`events.${i}.kind`,e.kind,[['expense','Cheltuială'],['income','Venit']])}</div><button class="danger" data-av-click="removeItem('events',${i})">Elimină</button></div>`).join('')}<button data-av-click="addEvent()">+ Eveniment</button></div>`}
function calendar(){let start=date(calMonth+'-01'),days=new Date(start.getFullYear(),start.getMonth()+1,0).getDate(),offset=(start.getDay()+6)%7,delta=(start.getFullYear()-date(S.profile.asof).getFullYear())*12+start.getMonth()-date(S.profile.asof).getMonth(),model=schedule(Math.max(2,Math.min(180,delta+2))),map=Object.fromEntries(model.daily.map(d=>[d.ds,d])),m=model.monthly.find(m=>m.key===calMonth),ev=model.events.filter(e=>e.ds.startsWith(calMonth));return `<div class="card"><div class="row"><button data-av-click="moveMonth(-1)">‹</button><h2 style="margin:0">${monthLabel(calMonth)}</h2><button data-av-click="moveMonth(1)">›</button></div><div class="fields"><label>Alege luna<input type="month" id="calpick" value="${esc(calMonth)}" data-av-change="calMonth=this.value||calMonth;render()"></label></div><div class="grid">${metric('Intrări (inclusiv credit reutilizat)',money(m?.in||0))}${metric('Ieșiri',money(m?.out||0))}${metric('Sold final',m?money(m.bal):'—','Provizoriu',m?.bal<0?'bad':'good')}</div><p class="tiny muted">Tichete: ${iso(ticketDate(start.getFullYear(),start.getMonth()))} · ${money(S.profile.tickets)} (separat de numerar)</p><div class="calendar">${['Lu','Ma','Mi','Jo','Vi','Sâ','Du'].map(x=>`<div class="dayhead">${x}</div>`).join('')}${Array.from({length:offset},()=>'<div class="day blank"></div>').join('')}${Array.from({length:days},(_,i)=>{let d=map[calMonth+'-'+String(i+1).padStart(2,'0')];return `<div class="day ${d?.bal<0?'negative':d?.events.some(e=>e.kind==='income')?'positive':''}"><b>${i+1}</b>${d?`<span class="${d.flow<0?'bad':'good'}">${d.flow?money(d.flow):'—'}</span><br><small>${money(d.bal)}</small>`:'<small>—</small>'}</div>`}).join('')}</div><p class="tiny muted">Valoarea de sus: fluxul zilei. Valoarea de jos: soldul consolidat de la sfârșitul zilei. În aceeași zi, ordinea încasărilor și plăților poate schimba lichiditatea necesară.</p></div><div class="card"><h2>Tranzacții planificate</h2>${table(['Data','Descriere','Flux'],ev.map(e=>[esc(e.ds),esc(e.name),`<span class="${e.amount<0?'bad':'good'}">${dec(e.amount)}</span>`]))}</div>${notice()}`}
function future(){let sc=S.scenario,months=Math.max(1,Math.min(180,n(sc.months))),b=schedule(months),s=schedule(months,true),rf=refi(),r=rf.ready?schedule(months,true,true):null;return `<div class="card"><h2>Scenarii și teste de rezistență</h2><div class="fields">${fld('Orizont luni (1–180)','scenario.months',sc.months,'number','max="180" min="1"')}${fld('Reducere salarială %','scenario.salaryCut',sc.salaryCut,'number','max="100"')}${fld('Cheltuială neprevăzută','scenario.shock',sc.shock)}${fld('Data cheltuielii','scenario.shockDate',sc.shockDate,'date')}</div>${chk('Preiau toate ratele părinților imediat','scenario.allParents',sc.allParents)}${chk('Nu mai reutilizez creditul ING','scenario.cardStop',sc.cardStop)}<p class="muted tiny">Bugetul de bază rămâne neschimbat. Preluarea individuală a ratelor poate fi stabilită și în fișa creditului. Reducerea salarială se aplică pe întreg orizontul.</p></div><div class="grid">${metric('Sold final – bază',money(b.bal),'Ipotezele actuale')}${metric('Sold final – scenariu',money(s.bal),'Diferență: '+money(s.bal-b.bal),s.bal>=0?'good':'bad')}${metric('Primul deficit – scenariu',s.first?s.first.ds:'Niciunul în model','Minim: '+money(s.low))}${metric('Sold ING – scenariu',money(s.cardBal),'Model constant, nu grafic bancar')}${metric('Necesar maxim de lichiditate',money(Math.max(0,-s.intradayLow)),'Deficit maxim în ordinea simulată a plăților')}${metric('Rezervă la final',money(s.bal-n(S.profile.buffer)),'Diferență față de ținta stabilită',s.bal>=n(S.profile.buffer)?'good':'bad')}</div><div class="card"><h2>Evoluție comparată</h2>${graph([{vals:[cash(),...b.monthly.map(m=>m.bal)],color:'#6ee7bd'},{vals:[cash(),...s.monthly.map(m=>m.bal)],color:'#ff9aab'},...(r?[{vals:[cash(),...r.monthly.map(m=>m.bal)],color:'#87b9ff'}]:[])])}<p class="tiny"><span class="good">● Bază</span>　<span class="bad">● Scenariu</span>　${r?'<span style="color:#87b9ff">● Cu refinanțare</span>':''}</p>${table(['Lună','Bază','Scenariu','Cu refinanțare'],b.monthly.map((m,i)=>[monthLabel(m.key),money(m.bal),money(s.monthly[i]?.bal),r?money(r.monthly[i]?.bal):'—']))}</div><div class="card"><h2>Simulator refinanțare · rate egale</h2><p class="muted tiny">Selectează creditele pe care vrei să le înlocuiești. Soldurile sunt cele introduse la data de referință, nu soldurile viitoare calculate la data refinanțării. Actualizează-le înainte de a compara o ofertă reală.</p>${S.debts.map(d=>`<label class="check"><input type="checkbox" ${sc.refiIds.includes(d.id)?'checked':''} data-av-change="toggleRefiIndex4(${S.debts.indexOf(d)},this.checked)">${esc(d.name)} · ${known(d.balance)?money(d.balance):'sold necunoscut'} · ${money(d.rate)}/lună</label>`).join('')}<div class="fields">${fld('Durată (luni)','scenario.refiMonths',sc.refiMonths,'number','min="1" max="360"')}${fld('Dobândă nominală anuală %','scenario.refiRate',sc.refiRate)}${fld('Costuri finanțate suplimentare','scenario.refiFees',sc.refiFees)}${fld('Prima rată / data înlocuirii','scenario.refiDate',sc.refiDate,'date')}</div>${rf.ready?`<div class="grid">${metric('Principal simulat',money(rf.principal))}${metric('Rată nouă',dec(rf.payment))}${metric('Diferență față de ratele selectate',dec(rf.old-rf.payment),'Nu înseamnă economie la costul total')}${metric('Total de rambursat',dec(rf.payment*n(sc.refiMonths)),'Fără costuri externe suplimentare')}</div><p class="tiny muted">Refinanțarea simulată trece noua rată în sarcina ta. Nu presupune acceptul băncii sau posibilitatea de a prelua creditele altor titulari. Rata estimată exclude asigurările neintroduse. Sold final în scenariu cu refinanțare: ${money(r.bal)}.</p>`:'<div class="notice">Completează soldurile creditelor selectate, dobânda și durata. Nu generăm o ofertă pe baza datelor lipsă.</div>'}</div>${notice()}`}
function history(){let rows=[...HISTORY.monthly,...S.historyExtra].filter(r=>(histYear==='all'||r[0].startsWith(histYear))&&(histBank==='all'||r[1]===histBank));let salary=rows.filter(r=>r[2]==='Salariu'),g=rows.filter(r=>r[2]==='Jocuri de noroc'),sum=(r,i)=>r.reduce((s,x)=>s+n(x[i]),0);let years=[...new Set([...HISTORY.monthly,...S.historyExtra].map(r=>r[0].slice(0,4)))].sort();let yr=years.map(y=>{let a=rows.filter(r=>r[0].startsWith(y)&&r[2]==='Salariu'),b=rows.filter(r=>r[0].startsWith(y)&&r[2]==='Jocuri de noroc');return [y,a.length?money(sum(a,3)):'—',a.length||'—',b.length?money(sum(b,4)):'—',b.length?money(sum(b,3)):'—',b.length?money(sum(b,3)-sum(b,4)):'—']});let cats=[...new Set(rows.map(r=>r[2]))].map(c=>{let a=rows.filter(r=>r[2]===c);return [esc(c),dec(sum(a,3)),dec(sum(a,4)),sum(a,5)]});return `<div class="card"><h2>Acoperire și filtre</h2><div class="fields"><label>An<select data-av-change="histYear=this.value;render()"><option value="all">Toți anii</option>${years.map(y=>`<option ${histYear===y?'selected':''}>${y}</option>`).join('')}</select></label><label>Sursă<select data-av-change="histBank=this.value;render()">${[['all','Toate'],['Raiffeisen','Raiffeisen'],['Revolut','Revolut']].map(([v,l])=>`<option value="${v}" ${histBank===v?'selected':''}>${l}</option>`).join('')}</select></label></div><p class="tiny muted">${HISTORY.count.toLocaleString('ro-RO')} înregistrări normalizate; agregări lunare, fără nume, IBAN sau date de identificare.</p>${table(['Sursă','Perioadă'],HISTORY.coverage.map(c=>[esc(c.bank),esc(c.period)]))}</div><div class="grid">${metric('Salarii identificate',money(sum(salary,3)),salary.length+' luni în selecție')}${metric('Plăți identificate către operatori',money(sum(g,4)),'Flux, nu pierdere')}${metric('Încasări de la operatori',money(sum(g,3)))}${metric('Diferență netă identificată',money(sum(g,3)-sum(g,4)),'Clasificare automată orientativă','bad')}</div><div class="card"><h2>Pe ani</h2>${table(['An','Salarii','Luni','Plăți jocuri','Încasări jocuri','Net jocuri'],yr)}</div><div class="card"><h2>Fluxuri pe categorii</h2>${table(['Categorie','Intrări','Ieșiri','Înregistrări'],cats)}<p class="tiny muted">Intrările și ieșirile brute pot include transferuri între conturi. Nu reprezintă venituri și cheltuieli consolidate. Paysafecard, transferurile și numerarul neclar nu sunt atribuite automat jocurilor. Clasificarea după denumiri poate omite operatori și diferă de analiza anterioară; nu este un calcul fiscal sau o pierdere certificată. Comisioanele Revolut din câmpul Fee nu sunt adăugate separat.</p></div><div class="card"><h2>Detalii lunare</h2>${table(['Lună','Sursă','Categorie','Intrări','Ieșiri'],rows.map(r=>[esc(r[0]),esc(r[1]),esc(r[2]),dec(r[3]),dec(r[4])]))}</div>`}
function data(){return `<div class="card"><h2>Vault și backup</h2><p>Datele se salvează criptat în browser, fără server financiar. Exportă un backup criptat pentru a transfera datele pe alt dispozitiv. Păstrează parola: nu poate fi recuperată.</p><div class="actions"><button class="primary" data-av-click="backup()">Exportă backup criptat</button><button data-av-click="$('restore').click()">Importă backup JSON</button><input type="file" id="restore" accept=".json,application/json" hidden style="display:none" data-av-change="restoreFile(this.files[0])"><button data-av-click="exportForecast()">Exportă prognoza CSV</button></div></div><div class="card"><h2>Metodologie și limite</h2><p>Istoricul agregat este păstrat separat de tranzacțiile importate individual, pentru a evita însumarea dublă. Creditele fără scadență finală continuă pe tot orizontul ales; dobânzile creditelor existente sunt informative. Refinanțarea este estimată prin anuitate; soldurile la data refinanțării trebuie introduse manual. Cardul ING modelează fluxurile de plată și reutilizare, nu toate tranșele contractuale. Prognozele sunt condiționate de datele disponibile. Tichetele sunt separate. Nu sunt incluse automat taxe, inflație, comisioane sau întârzieri.</p><p>Motorul de inteligență este bazat pe reguli și calcule locale, nu un model lingvistic. Nu există telemetrie sau conexiuni externe în aplicație.</p><button class="danger" data-av-click="resetAll()">Resetează profilul editabil</button></div>`}

