function future2(){let b=schedule(horizon),s=schedule(horizon,true),delta=s.bal-b.bal;return '<div class="v2intro"><div class="v2eyebrow">SIMULATOR INTERACTIV</div><h2>Vezi impactul înainte să decizi.</h2><p class="muted">Scenariile nu modifică bugetul de bază.</p></div><div class="v2links">'+[1,3,6,12].map(m=>'<button class="'+(m===horizon?'selected':'')+'" data-av-click="pickHorizon('+m+')">'+m+' luni</button>').join('')+'</div><div class="v2presets">'+[['base','Normal','Buget actual'],['income','Venit redus','−15% salariu'],['parents','Preiau ratele','Obligații familiale'],['card','Oprire reutilizare','Card de credit']].map(([id,t,d])=>'<button data-av-click="preset(\''+id+'\')"><b>'+t+'</b><small>'+d+'</small></button>').join('')+'</div><div class="card v2chart"><div class="v2eyebrow">SOLD ESTIMAT · '+horizon+' LUNI</div><div class="v2balance '+(s.bal<0?'bad':'')+'">'+money(s.bal)+'</div><p class="'+(delta<0?'bad':'good')+'">'+(delta>0?'+':'')+money(delta)+' față de bază</p>'+graph([{vals:[cash(),...b.monthly.map(x=>x.bal)],color:'#c2a9fa',label:'Bază'},{vals:[cash(),...s.monthly.map(x=>x.bal)],color:'#86a8ff',label:'Scenariu'}])+'<p class="tiny muted">'+(isReady()?'Model condiționat':'Date incomplete')+' · Lavandă: bază. Albastru: scenariu.</p></div><div class="grid">'+metric('Minim în cursul zilei',money(s.intradayLow),'Scenariu')+metric('Primul deficit',s.first?.ds||'Niciunul în model')+'</div>'+links([['calendar','Calendar zilnic'],['decision','Test achiziție'],['advanced','Refinanțare / simulare avansată']])}
function debts2(){let r=rates(),other=rates(true)-r;return '<section class="v2hero"><div class="v2eyebrow">OBLIGAȚII LUNARE</div><div class="v2balance">'+money(r)+'</div><p>Plătite de tine · '+money(other)+' suportate de alte persoane</p><div class="v2flow"><i style="flex:'+Math.max(0,r)+';background:#86a8ff"></i><i style="flex:'+Math.max(0,other)+';background:#e6c58c"></i></div></section><div class="card"><h2>Credite și card</h2>'+S.debts.map(d=>eventRow('Ziua '+d.day,d.name,(d.payer==='Eu'?'Plătit de tine':'Plătitor: '+d.payer)+' · '+(known(d.balance)?money(d.balance):'Sold neconfirmat'),money(d.rate))).join('')+eventRow('Card','Credit utilizat','Din '+money(S.card.limit),money(S.card.balance))+'</div><div class="card"><h2>Împrumuturi personale</h2>'+(S.personal.map(p=>eventRow('Datorie',p.name,'Neprogramat: '+money(Math.max(0,n(p.balance)-p.plan.reduce((s,e)=>s+n(e.amount),0))),known(p.balance)?money(p.balance):'—')).join('')||'<p class="muted">Nicio datorie introdusă.</p>')+'</div>'+links([['debtedit','Editează / adaugă datorii','primary'],['advanced','Simulează refinanțare']])}
function profile2(){let by={};for(let r of HISTORY.monthly)if(r[2]==='Salariu'&&r[0].startsWith(S.profile.asof.slice(0,4)))by[r[0]]=(by[r[0]]||0)+n(r[3]);let a=Object.values(by).filter(x=>x>0).sort((x,y)=>x-y);let op=a.length?[['Minim',a[0]],['Mediană',(a[(a.length-1)>>1]+a[a.length>>1])/2],['Medie',Math.round(a.reduce((x,y)=>x+y,0)/a.length)]]:[];return '<div class="v2intro"><div class="v2eyebrow">DATELE TALE</div><h2>Setează o dată. Ajustează când se schimbă.</h2></div><div class="card"><h2>Profil și backup</h2><p class="muted">Importă profilul pregătit sau un backup. Datele rămân în seiful local.</p><div class="actions"><button class="primary" data-av-click="openImport()">Importă profil / backup</button><button data-av-click="backup()">Exportă backup criptat</button><input type="file" id="restore" accept=".json,application/json" hidden style="display:none" data-av-change="restoreFile(this.files[0])"></div></div><div class="card"><h2>Venit obișnuit</h2>'+fld('Salariu net lunar','profile.salary',S.profile.salary)+chk('Confirm salariul de lucru','profile.salaryConfirmed',S.profile.salaryConfirmed)+fld('Tichete de masă','profile.tickets',S.profile.tickets)+'<div class="v2links">'+op.map(([t,v])=>'<button data-av-click="applySalary('+v+')">'+t+' · '+money(v)+'</button>').join('')+'</div><p class="tiny muted">Salariu: a patra zi lucrătoare. Tichete: pe 10 sau ziua lucrătoare anterioară. Excepții în setările detaliate.</p></div>'+links([['budget','Conturi, venituri, recurențe'],['history','Istoric financiar'],['intelligence','Date lipsă și explicații'],['data','Siguranță și metodologie']])}

