const norm3=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const date3=x=>{let s=String(x??'').trim(),m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m){let t=s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/);if(t)m=[t[0],t[3],t[2].padStart(2,'0'),t[1].padStart(2,'0')]}if(!m&&/^\d{5}(\.\d+)?$/.test(s)){let z=new Date(Date.UTC(1899,11,30)+Math.floor(Number(s))*86400000);return z.toISOString().slice(0,10)}if(!m)return '';let d=m.slice(1).join('-');return /^\d{4}-\d{2}-\d{2}$/.test(d)&&iso(date(d))===d?d:''};
