function csv3(text){text=text.replace(/^\uFEFF/,'');let first=text.split(/\r?\n/).slice(0,20),sep=first.some(x=>/amount|suma debit/i.test(x)&&x.split(';').length>x.split(',').length)?';':first.some(x=>x.includes('\t')&&/amount|suma debit/i.test(x))?'\t':',';let rows=[],row=[],field='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++}else quote=!quote}else if(c===sep&&!quote){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);rows.push(row);row=[];field=''}else field+=c}if(quote)throw Error('CSV: ghilimele neînchise');if(field||row.length){row.push(field);rows.push(row)}return rows}
