function startRule4(){let idx=Number($('ruleindex4')?.value),cat=$('rulecat4')?.value,t=tx3()[idx];if(!t||!categories3.includes(cat)){toast('Alege o tranzacție și o categorie.');return}let key=merchant4(t),sign=Math.sign(t.amount),matches=tx3().filter(v=>merchant4(v)===key&&Math.sign(v.amount)===sign&&!v.transferGroup);rulePreview4={key,sign,cat,count:matches.length,label:t.description};render(true)}
function confirmRule4(){let p=rulePreview4;if(!p)return;S.categoryRules=[...rules4().filter(r=>r.key!==p.key||r.sign!==p.sign),{key:p.key,sign:p.sign,category:p.cat}];for(let t of tx3())if(!t.transferGroup&&merchant4(t)===p.key&&Math.sign(t.amount)===p.sign){t.category=p.cat;t.reviewed=true}rulePreview4=null;commit();toast('Regulă salvată și aplicată')}
