function removeRule4(i){S.categoryRules=rules4().filter((x,j)=>j!==i);commit()}
function rulesUI4(){let t=tx3(),seen=new Set(),samples=[];for(let i=t.length-1;i>=0&&samples.length<80;i--){let x=t[i],k=merchant4(x)+'|'+Math.sign(x.amount);if(x.transferGroup||seen.has(k))continue;seen.add(k);samples.push([i,x])}let p=rulePreview4;return '<div class="card"><div class="row"><h2>Clasificare în grup</h2><span class="pill">'+rules4().length+' reguli</span></div><p class="muted tiny">Alege un exemplu. Regula se aplică numai descrierii identice și aceluiași sens al sumei, inclusiv la importuri viitoare.</p>'+(samples.length?'<div class="fields"><label>Exemplu<select id="ruleindex4">'+samples.map(([i,x])=>'<option value="'+i+'">'+esc(x.description.slice(0,75))+' · '+money(x.amount)+'</option>').join('')+'</select></label><label>Categorie<select id="rulecat4">'+categories3.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select></label></div><button data-av-click="startRule4()">Verifică potrivirile</button>':'<p>Importă tranzacții pentru a crea reguli.</p>')+(p?'<div class="notice"><b>'+p.count+' tranzacții</b> · '+esc(p.cat)+'<p>'+esc(p.label)+'</p><button class="primary" data-av-click="confirmRule4()">Aplică regula</button> <button data-av-click="cancelRule4()">Renunță</button></div>':'')+'<details><summary>Reguli salvate</summary>'+rules4().map((r,i)=>'<div class="row v2line"><span>'+esc(r.key.slice(0,65))+' → '+esc(r.category)+'</span><button data-av-click="removeRule4('+i+')">Elimină regula</button></div>').join('')+'</details></div>'}
function findTransfers4(){let tx=tx3(),pos=new Map(),candidates=[],possible=t=>!t.transferGroup&&t.category==='Transfer propriu / posibil';for(let i=0;i<tx.length;i++){let t=tx[i];if(t.amount>0&&possible(t)){let k=Math.round(t.amount*100)+'|'+t.date;(pos.get(k)||pos.set(k,[]).get(k)).push(i)}}let pairs=[],use=new Map();for(let i=0;i<tx.length;i++){let t=tx[i];if(t.amount>=0||!possible(t))continue;let match=[];for(let off of [-1,0,1]){let k=Math.round(-t.amount*100)+'|'+iso(add(date(t.date),off));for(let j of pos.get(k)||[])if(tx[j].account!==t.account)match.push(j)}if(match.length===1){pairs.push([i,match[0]]);use.set(match[0],(use.get(match[0])||0)+1)}}return pairs.filter(x=>use.get(x[1])===1)}
