function confirmTransfer4(i){let pair=transferPairs4[i],t=tx3();if(!pair||t[pair[0]].transferGroup||t[pair[1]].transferGroup)return;let id=uid();for(let j of pair){t[j].transferGroup=id;t[j].category='Transfer propriu / posibil';t[j].reviewed=true}transferPairs4=transferPairs4.filter((p,k)=>k!==i);commit()}
