function transferUI4(){let t=tx3(),confirmed=t.filter(x=>x.transferGroup).length;return '<div class="card"><h2>Transferuri între conturi</h2><p class="tiny muted">Caută valori opuse identice, la maximum o zi distanță, între conturi diferite, numai în categoria de transfer posibil. Nu confirmă automat niciun transfer.</p><div class="row"><b>'+confirmed+' tranzacții asociate</b><button data-av-click="scanTransfers4()">Caută perechi</button></div>'+transferPairs4.slice(0,30).map(([i,j],k)=>'<div class="v4pair"><div><b>'+money(-t[i].amount)+'</b><small>'+esc(t[i].date+' · '+t[i].account)+' → '+esc(t[j].account+' · '+t[j].date)+'</small><small>'+esc(t[i].description.slice(0,80))+' / '+esc(t[j].description.slice(0,80))+'</small></div><button data-av-click="confirmTransfer4('+k+')">Confirmă</button></div>').join('')+(transferPairs4.length>30?'<p class="tiny muted">Primele 30 din '+transferPairs4.length+'.</p>':'')+'<details><summary>Asocieri confirmate / anulare</summary>'+t.map((x,i)=>[x,i]).filter(([x])=>x.transferGroup&&x.amount<0).slice(0,100).map(([x,i])=>'<div class="row v2line"><span>'+esc(x.date)+' · '+money(-x.amount)+' · '+esc(x.account)+'</span><button data-av-click="undoTransfer4('+i+')">Anulează</button></div>').join('')+'</details></div>'}
function monthly4(){let tx=tx3(),months=[...new Set(tx.map(t=>t.date.slice(0,7)))].sort();if(!months.length)return '<div class="card"><h2>Analiză lunară</h2><p>Importă tranzacții pentru a explora fluxurile.</p></div>';if(!months.includes(month4))month4=months.at(-1);let rows=tx.filter(t=>t.date.startsWith(month4)&&(filterAccount4==='all'||t.account===filterAccount4)),accounts=[...new Set(tx.map(t=>t.account))].sort(),confirmed=rows.filter(t=>t.transferGroup),uncertain=rows.filter(t=>!t.transferGroup&&['Transfer propriu / posibil','Necategorizat'].includes(t.category)),classified=rows.filter(t=>!t.transferGroup&&!['Transfer propriu / posibil','Necategorizat'].includes(t.category)),total=(arr,sign)=>arr.reduce((s,t)=>s+Math.max(0,t.amount*sign),0),out=total(classified,-1),inc=total(classified,1),unknown=total(uncertain,-1),by={};for(let t of classified)if(t.amount<0)by[t.category]=(by[t.category]||0)-t.amount;let list=Object.entries(by).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...list.map(x=>x[1])),prev=months[months.indexOf(month4)-1],prior=tx.filter(t=>prev&&t.date.startsWith(prev)&&(filterAccount4==='all'||t.account===filterAccount4)&&!t.transferGroup&&!['Transfer propriu / posibil','Necategorizat'].includes(t.category)&&t.amount<0),delta=prev?out-total(prior,-1):null;return '<div class="v3banner"><small>ANALIZĂ REALĂ · TRANZACȚII IMPORTATE</small><h2>Unde s-au dus banii?</h2><p>Transferurile confirmate sunt separate de restul fluxurilor. Sumele neclasificate rămân vizibile.</p></div><div class="card"><div class="fields"><label>Lună<select data-av-change="monthSelect4(this.value)">'+months.slice().reverse().map(x=>'<option '+(x===month4?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>Cont<select data-av-change="accountSelect4(this.value)"><option value="all">Toate</option>'+accounts.map(x=>'<option '+(x===filterAccount4?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></label></div><div class="grid">'+metric('Intrări clasificate',money(inc))+metric('Ieșiri clasificate',money(out))+metric('Ieșiri de verificat',money(unknown))+metric('Transferuri confirmate · ieșiri',money(total(confirmed,-1)))+'</div><p class="tiny muted">Acoperirea extraselor poate fi parțială. Nu reprezintă venit net sau cheltuială totală. Taxele din Fee rămân informative.</p></div><div class="card"><h2>Categorii de ieșiri</h2>'+list.map(([k,v])=>'<div class="v4cat"><div class="row"><span>'+esc(k)+'</span><b>'+money(v)+'</b></div><div class="v2flow"><i style="flex:'+v/max+';background:#86a8ff"></i><i style="flex:'+Math.max(0,1-v/max)+'"></i></div></div>').join('')+(delta===null?'':'<p class="tiny muted">Diferență brută față de luna precedentă disponibilă ('+prev+'): '+money(delta)+'. Nu este o tendință confirmată dacă acoperirea diferă.</p>')+'</div>'+transferUI4()+rulesUI4()+links([['bank','Import și tranzacții'],['history','Istoric agregat anterior']])}
