function cashSave6(){let raw=$('cashamt6')?.value,v=Number(raw),note=String($('cashnote6')?.value||'').trim().slice(0,100);if(!knownCash()||S.profile.asof!==today()){toast('Actualizează mai întâi soldul de astăzi.');return}if(raw===''||!Number.isFinite(v)||v<=0||v>1e8){toast('Introdu o sumă pozitivă validă.');return}let before=cash(),after=Math.round((before+(cashKind6==='expense'?-v:v))*100)/100;if(!confirm('Soldul devine '+money(after)+'. Confirmi că operațiunea nu este deja inclusă în sold?'))return;S.profile.cashTotal=after;logCash6(before,after,cashKind6,note||(cashKind6==='expense'?'Cheltuială':'Încasare'),today());cashOpen6=false;commit();toast('Mișcare înregistrată')}
