root.addEventListener('change',e=>{let el=e.target,p=el.dataset.path;if(!p)return;let v=el.type==='checkbox'?el.checked:el.type==='number'&&el.value!==''?Number(el.value):el.value;if(el.type==='number'&&el.value!==''&&!el.checkValidity()){toast('Valoare invalidă. Verifică limitele.');render(true);return}if(p==='profile.asof'&&!v){toast('Data de referință este obligatorie.');render(true);return}set(p,v);if(el.type==='checkbox'||el.tagName==='SELECT'){render(true)}else{clearTimeout(updateTimer);updateTimer=setTimeout(()=>{if(!document.activeElement?.matches('input,select,textarea'))render(true)},180)}});function commit(){persist();render(true)}function removeItem(k,i){if(confirm('Elimini această înregistrare?')){S[k].splice(i,1);commit()}}function addDebt(){S.debts.push(debt(uid(),'Credit nou','Eu','Eu',0,15));commit()}function addPersonal(){S.personal.push({id:uid(),name:'Împrumut nou',balance:'',plan:[]});commit()}function addPlan(i){S.personal[i].plan.push({id:uid(),date:iso(add(date(S.profile.asof),30)),amount:0});commit()}function delPlan(i,j){S.personal[i].plan.splice(j,1);commit()}function addAccount(){S.accounts.push({id:uid(),name:'Cont nou',balance:'',minTurnover:'',fee:''});commit()}function addRecurring(){S.recurring.push({id:uid(),name:'Cheltuială nouă',amount:0,frequency:'monthly',day:1,anchor:S.profile.asof});commit()}function addEvent(){S.events.push({id:uid(),name:'Eveniment nou',date:iso(add(date(S.profile.asof),1)),amount:0,kind:'expense'});commit()}function moveMonth(i){let d=date(calMonth+'-01');d.setMonth(d.getMonth()+i);calMonth=monthKey(d);render()}function toggleRefi(id,on){S.scenario.refiIds=on?[...new Set([...S.scenario.refiIds,id])]:S.scenario.refiIds.filter(x=>x!==id);commit()}function download(name,content,type){plugin.exportFile(name,content).then(p=>toast("Salvat: "+p)).catch(e=>toast("Eroare export: "+e.message))}function backup(){download('Avelis-backup-'+today()+'.json',JSON.stringify({state:S,history:HISTORY,theme:root.dataset.theme,initial:DEFAULT}),'application/json')}function validBackup(x){return x&&x.version===1&&x.profile&&/^\d{4}-\d{2}-\d{2}$/.test(x.profile.asof)&&x.card&&x.scenario&&['accounts','debts','personal','recurring','events','historyExtra'].every(k=>Array.isArray(x[k]))&&x.personal.every(p=>Array.isArray(p.plan))&&Array.isArray(x.scenario.refiIds)}async function restoreFile(f){if(!f)return;try{let raw=JSON.parse(await f.text());if(raw.format==='avelis-vault-1'){let pass=prompt('Parola backup-ului');if(!pass)return;raw=await decryptRecord(raw,pass)}let x=raw.state||raw;if(!validBackup(x))throw Error('Format invalid');if(confirm('Înlocuiești toate datele editabile cu backup-ul?')){S=structuredClone(x);DEFAULT=structuredClone(raw.initial&&validBackup(raw.initial)?raw.initial:x);if(raw.history&&Array.isArray(raw.history.monthly)&&Array.isArray(raw.history.coverage))HISTORY={...raw.history,count:Number(raw.history.count)||0};commit();toast('Backup restaurat')}}catch(e){toast('Backup invalid sau incompatibil.')}}function resetAll(){if(confirm('Ștergi toate modificările? Exportă backup înainte.')){S=structuredClone(DEFAULT);commit();toast('Date resetate')}}function exportForecast(){let a=schedule(S.scenario.months);let csv='Data;Flux net RON;Sold final RON\n'+a.daily.map(d=>[d.ds,d.flow.toFixed(2),d.bal.toFixed(2)].join(';')).join('\n');download('Avelis-prognoza.csv','\uFEFF'+csv,'text/csv;charset=utf-8')}

const navPaths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',debts:'M3 9h18M5 9v9M10 9v9M14 9v9M19 9v9M3 21h18M2 7l10-5 10 5',budget:'M3 6h18v15H3zM3 10h18M16 15h2',calendar:'M3 5h18v16H3zM7 2v6M17 2v6M3 10h18',future:'M3 20V4M3 20h18M6 16l5-5 4 2 6-8',decision:'M12 2v20M2 12h20M6 6l12 12M18 6L6 18',history:'M3 12a9 9 0 1 0 3-7M3 3v6h6M12 7v6l4 2',data:'M4 4h16v16H4zM8 4v7h8V4M8 20v-6h8v6'};function navIcon(id){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><path d="${navPaths[id]||navPaths.overview}"/></svg>`}function toggleTheme(){root.dataset.theme=root.dataset.theme==='light'?'dark':'light';persist()}

function intelligence(){let salaryByMonth={};for(let r of HISTORY.monthly)if(r[2]==='Salariu'&&r[0].startsWith(S.profile.asof.slice(0,4)))salaryByMonth[r[0]]=(salaryByMonth[r[0]]||0)+n(r[3]);let vals=Object.values(salaryByMonth).sort((a,b)=>a-b),median=vals.length?(vals[(vals.length-1)>>1]+vals[vals.length>>1])/2:null,mean=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null,low=vals.length?vals[0]:null,high=vals.length?vals.at(-1):null,base=schedule(12),ownRate=rates(),parent=rates(true)-ownRate,margin=net(),checks=[['Solduri disponibile',knownCash(),'Completează fiecare cont; zero înseamnă sold verificat.','budget'],['Cheltuieli de trai',known(S.profile.extraLiving),'Completează cheltuielile peste tichete.','budget'],['Solduri credite',S.debts.every(d=>known(d.balance)),'Soldul fiecărui credit este necesar pentru refinanțare.','debts'],['Date finale',S.debts.every(d=>!!d.end),'Necesare pentru calendarul eliberării ratelor.','debts'],['Dobânzi',S.debts.every(d=>known(d.interest)),'Necesare pentru evaluarea costurilor.','debts'],['Extras card',known(S.card.due)&&known(S.card.day)&&known(S.card.reuse),'Plată, scadență și reutilizare efectivă.','debts'],['Datorii personale',S.personal.every(p=>p.plan.reduce((s,e)=>s+n(e.amount),0)>=n(p.balance)),'Planifică tranșele rămase.','debts']],done=checks.filter(x=>x[1]).length,g=HISTORY.monthly.filter(r=>r[2]==='Jocuri de noroc'),loss=g.reduce((s,r)=>s+n(r[3])-n(r[4]),0);return `<div class="card hero"><div><span class="pill">Inteligență locală · reguli verificabile</span><h2>Claritatea începe cu datele.</h2><div class="big">${done}/${checks.length}</div><p class="hero-sub">Verificări completate. Acesta nu este un scor de sănătate financiară.</p><div class="profile-progress"><span style="width:${done/checks.length*100}%"></span></div></div></div><div class="intelligence-grid"><div class="card"><div class="signal">LICHIDITATE</div><h2>${base.first?'Deficit proiectat':'Niciun deficit în model'}</h2><p>${base.first?'Prima zi: '+base.first.ds:'În următoarele 12 luni'}. Sold minim: ${money(base.low)}.</p><p class="tiny muted">Soldurile și costurile necunoscute pot modifica rezultatul.</p><button data-av-click="go('calendar')">Vezi calendarul</button></div><div class="card"><div class="signal">OBLIGAȚII FAMILIALE</div><h2>${money(margin-parent)} / lună</h2><p>Marjă dacă preiei toate ratele; diferență de ${money(parent)} față de situația actuală. Înainte de ING net și datorii personale.</p><button data-av-click="go('future')">Compară scenarii</button></div><div class="card"><div class="signal">CARD DE CREDIT</div><h2>${money(S.card.balance)} utilizat</h2><p>${known(S.card.due)&&known(S.card.reuse)?'Plată netă estimată: '+money(dueCard())+'.':'Datele extrasului lipsesc.'} Reutilizarea creditului nu este venit și nu reduce automat soldul.</p><button data-av-click="go('debts')">Completează extrasul</button></div><div class="card"><div class="signal">ISTORIC · FLUX NET</div><h2>${money(loss)}</h2><p>Clasificare automată orientativă din istoricul agregat, diferită de analiza inițială. Necesită reconciliere; nu reprezintă pierdere certificată. Bugetul viitor nu presupune recuperarea sumelor.</p><button data-av-click="go('history')">Explorează istoricul</button></div></div><div class="card"><h2>Salariu observat · ${vals.length} luni</h2>${vals.length?`<div class="grid">${metric('Minim',money(low))}${metric('Mediană',money(median))}${metric('Medie',money(mean))}${metric('Maxim',money(high))}</div><div class="actions"><button data-av-click="applySalary(${low})">Folosește minimul</button><button data-av-click="applySalary(${median})">Folosește mediana</button><button data-av-click="applySalary(${Math.round(mean)})">Folosește media</button></div><p class="tiny muted">Alegerea modifică salariul de lucru din buget, nu istoricul.</p>`:'<p>Nu există salarii agregate pentru anul selectat.</p>'}</div><div class="card"><h2>Profil financiar · ce lipsește</h2>${checks.map(([name,ok,why,view])=>`<div class="profile-row"><div><strong>${ok?'✓':'○'} ${name}</strong><p class="muted">${why}</p></div><button data-av-click="go('${view}')">${ok?'Verifică':'Completează'}</button></div>`).join('')}</div>`}function applySalary(v){S.profile.salary=v;S.profile.salaryConfirmed=true;commit()}

